import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Tool reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1787002545000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tool-reference" tabindex="-1">Tool reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to “Tool reference”">​</a></h1><p>All 28 tools: 11 read, 17 write. With <code>LINKWARDEN_READ_ONLY=true</code> the write tools are not registered at all — they do not appear in <code>tools/list</code>.</p><p>Tools marked <strong>write, destructive</strong> need a confirmation token: call them once without <code>confirm_token</code> to get one, then again with it. The token is bound to the exact target and expires after five minutes. See <a href="/guide/security">Security</a>.</p><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><h3 id="search-links" tabindex="-1"><code>search_links</code> <a class="header-anchor" href="#search-links" aria-label="Permalink to “search_links”">​</a></h3><p><strong>Search and list links</strong> — read-only</p><p>Searches bookmarks, or lists them when no query is given. This is the way to find links — there is no separate list tool, and the older /links listing route is deprecated upstream. Plain text matches the title, URL, description and tag names of a link. IMPORTANT: the field-filter syntax below only works on instances that run Meilisearch. Linkwarden parses those filters exclusively in its Meilisearch branch; without it the whole query is matched as one literal substring, so <code>tag:news</code> searches for the characters &quot;tag:news&quot; and finds nothing. Use the collection_id, tag_id and pinned_only arguments instead — those are applied by the database and work either way. list_collections and list_tags give you the ids. Where Meilisearch is available the filters are: url: name: description: type: collection: tag: pinned: public: before: after: Quote values that contain spaces, e.g. collection:&quot;Read later&quot;. Prefix a filter with ! to negate it, e.g. !tag:archive. pinned: and public: take true or false; before: and after: take a date such as 2026-01-31. If the instance sets SEARCH_FILTER_LIMIT, field filters beyond that count are dropped silently, so prefer few, specific filters. Returns at most 100 links plus a next_cursor for the following page. Article text is not included; use get_link_content for that.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>no</td><td>Search query, see the syntax above. Omit to list links.</td></tr><tr><td><code>collection_id</code></td><td>integer</td><td>no</td><td>Restrict the result to this collection</td></tr><tr><td><code>tag_id</code></td><td>integer</td><td>no</td><td>Restrict the result to this tag</td></tr><tr><td><code>pinned_only</code></td><td>boolean</td><td>no</td><td>Only return links pinned by the authenticated account</td></tr><tr><td><code>sort</code></td><td><code>&quot;date_newest&quot;</code> | <code>&quot;date_oldest&quot;</code> | <code>&quot;name_az&quot;</code> | <code>&quot;name_za&quot;</code></td><td>no</td><td>Sort order, default date_newest</td></tr><tr><td><code>cursor</code></td><td>integer</td><td>no</td><td>Opaque pagination cursor. Pass back the &quot;next_cursor&quot; value from a previous result verbatim; do not compute or increment it — depending on whether the instance runs Meilisearch it is either a row offset or the last id seen.</td></tr></tbody></table><h3 id="get-link" tabindex="-1"><code>get_link</code> <a class="header-anchor" href="#get-link" aria-label="Permalink to “get_link”">​</a></h3><p><strong>Get a link</strong> — read-only</p><p>Fetches one bookmark with its tags, collection and which preserved formats exist. Does not include the archived page text — use get_link_content for that.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the link — the &quot;id&quot; field returned by search_links, not its title or URL</td></tr></tbody></table><h3 id="get-link-content" tabindex="-1"><code>get_link_content</code> <a class="header-anchor" href="#get-link-content" aria-label="Permalink to “get_link_content”">​</a></h3><p><strong>Read the preserved text of a link</strong> — read-only</p><p>Returns the readable article text Linkwarden extracted and stored when it preserved the page, so a saved bookmark can be read without fetching the live site. Only the readable format is served: the screenshot, PDF and single-file HTML archives are binary or raw markup and are not useful as text. Long articles are returned in slices — pass the offset from the previous result to continue. If the link has no readable archive, the tool says so and represerve_link can create one.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the link — the &quot;id&quot; field returned by search_links, not its title or URL</td></tr><tr><td><code>offset</code></td><td>integer</td><td>no</td><td>Character offset to start at, default 0</td></tr><tr><td><code>max_chars</code></td><td>integer</td><td>no</td><td>Maximum characters to return, default 20000</td></tr></tbody></table><h3 id="list-collections" tabindex="-1"><code>list_collections</code> <a class="header-anchor" href="#list-collections" aria-label="Permalink to “list_collections”">​</a></h3><p><strong>List collections</strong> — read-only</p><p>Lists every collection the authenticated account owns or is a member of, with its link count. The list is flat: nesting is expressed through parentId, where null means the collection sits at the top level. Linkwarden does not page this route, so all collections come back at once.</p><p>Takes no parameters.</p><h3 id="get-collection" tabindex="-1"><code>get_collection</code> <a class="header-anchor" href="#get-collection" aria-label="Permalink to “get_collection”">​</a></h3><p><strong>Get a collection</strong> — read-only</p><p>Fetches one collection with its link count and the per-member create/update/delete permissions. Use search_links with collection_id to get the links inside it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>collection_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the collection — the &quot;id&quot; field returned by list_collections</td></tr></tbody></table><h3 id="list-tags" tabindex="-1"><code>list_tags</code> <a class="header-anchor" href="#list-tags" aria-label="Permalink to “list_tags”">​</a></h3><p><strong>List tags</strong> — read-only</p><p>Lists the tags of the authenticated account with the number of links each one is attached to. Tags cut across collections. The per-tag archival settings are included: null there means &quot;inherit the account default&quot;, which is not the same as false.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>search</code></td><td>string</td><td>no</td><td>Only return tags whose name contains this text</td></tr><tr><td><code>sort</code></td><td><code>&quot;date_newest&quot;</code> | <code>&quot;date_oldest&quot;</code> | <code>&quot;name_az&quot;</code> | <code>&quot;name_za&quot;</code> | <code>&quot;link_count_high_low&quot;</code> | <code>&quot;link_count_low_high&quot;</code></td><td>no</td><td>Sort order, default date_newest</td></tr><tr><td><code>cursor</code></td><td>integer</td><td>no</td><td>Opaque pagination cursor. Pass back the &quot;next_cursor&quot; value from a previous result verbatim; do not compute or increment it — depending on whether the instance runs Meilisearch it is either a row offset or the last id seen.</td></tr></tbody></table><h3 id="get-tag" tabindex="-1"><code>get_tag</code> <a class="header-anchor" href="#get-tag" aria-label="Permalink to “get_tag”">​</a></h3><p><strong>Get a tag</strong> — read-only</p><p>Fetches one tag with its archival settings. Use search_links with tag_id to get the links carrying it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>tag_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the tag — the &quot;id&quot; field returned by list_tags</td></tr></tbody></table><h3 id="get-current-user" tabindex="-1"><code>get_current_user</code> <a class="header-anchor" href="#get-current-user" aria-label="Permalink to “get_current_user”">​</a></h3><p><strong>Get the authenticated account</strong> — read-only</p><p>Reports which Linkwarden account the configured token belongs to and that account&#39;s archival defaults — which formats new links get preserved in, and whether duplicate URLs are rejected. Useful as a connectivity check and before creating links, because the defaults decide what get_link_content will later have to read.</p><p>Takes no parameters.</p><h3 id="get-dashboard" tabindex="-1"><code>get_dashboard</code> <a class="header-anchor" href="#get-dashboard" aria-label="Permalink to “get_dashboard”">​</a></h3><p><strong>Get the dashboard links</strong> — read-only</p><p>Returns the links Linkwarden shows on its dashboard: the most recently added ones together with everything the account has pinned, deduplicated. A quick &quot;what is going on here&quot; overview — use search_links for anything targeted.</p><p>Takes no parameters.</p><h3 id="list-rss-subscriptions" tabindex="-1"><code>list_rss_subscriptions</code> <a class="header-anchor" href="#list-rss-subscriptions" aria-label="Permalink to “list_rss_subscriptions”">​</a></h3><p><strong>List RSS subscriptions</strong> — read-only</p><p>Lists the RSS feeds this account subscribes to. Linkwarden polls them and files new entries as links in the configured collection.</p><p>Takes no parameters.</p><h3 id="get-worker-stats" tabindex="-1"><code>get_worker_stats</code> <a class="header-anchor" href="#get-worker-stats" aria-label="Permalink to “get_worker_stats”">​</a></h3><p><strong>Get preservation queue statistics</strong> — read-only</p><p>Reports how many links are waiting to be preserved, how many succeeded and how many failed, plus the search-index backlog. Use it to find out whether a page requested through represerve_link has been archived yet. Requires the instance administrator account (the id in NEXT_PUBLIC_ADMIN, 1 by default); every other account gets HTTP 403 here. The counts cover the whole instance, not just this account.</p><p>Takes no parameters.</p><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><h3 id="create-link" tabindex="-1"><code>create_link</code> <a class="header-anchor" href="#create-link" aria-label="Permalink to “create_link”">​</a></h3><p><strong>Create a link</strong> — write</p><p>Saves a bookmark. Linkwarden fetches the page title itself when no name is given, and queues the page for preservation according to the account defaults (get_current_user shows them). The collection is optional; without one the link lands in &quot;Unorganized&quot;. Naming a collection that does not exist creates it. If the account has &quot;prevent duplicate links&quot; enabled, saving a URL twice fails with HTTP 409.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>url</code></td><td>string</td><td>yes</td><td>URL to bookmark, including the scheme</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td>Title. Omit to let Linkwarden read it from the page.</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>collection_id</code></td><td>integer</td><td>no</td><td>Target collection. Mutually exclusive with collection_name.</td></tr><tr><td><code>collection_name</code></td><td>string</td><td>no</td><td>Target collection by name; it is created if it does not exist. Mutually exclusive with collection_id.</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>no</td><td>Tag names. Tags that do not exist yet are created.</td></tr></tbody></table><h3 id="update-link" tabindex="-1"><code>update_link</code> <a class="header-anchor" href="#update-link" aria-label="Permalink to “update_link”">​</a></h3><p><strong>Update a link</strong> — write</p><p>Changes a bookmark. Fields that are not given stay as they are: the tool reads the link first and merges, because the underlying route replaces the whole record and would otherwise clear the title, description and every tag. The tags argument REPLACES the tag list — pass the full set you want. Moving a link to another collection only works for the collection owner. Changing the URL is destructive and needs a confirmation token: Linkwarden deletes every preserved copy of the old page (screenshot, PDF, readable text, single-file HTML) and starts over.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the link — the &quot;id&quot; field returned by search_links, not its title or URL</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td>New title</td></tr><tr><td><code>url</code></td><td>string</td><td>no</td><td>New URL — destroys the existing preserved copies</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>collection_id</code></td><td>integer</td><td>no</td><td>Move the link to this collection (owner only)</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>no</td><td>Replacement tag list. Omit to keep the current tags, pass [] to remove all of them.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="set-link-pinned" tabindex="-1"><code>set_link_pinned</code> <a class="header-anchor" href="#set-link-pinned" aria-label="Permalink to “set_link_pinned”">​</a></h3><p><strong>Pin or unpin a link</strong> — write</p><p>Pins a link to the account&#39;s dashboard, or removes the pin. Pins are per account, so this only affects the account the token belongs to. Pinned links can be listed with search_links and pinned_only=true.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the link — the &quot;id&quot; field returned by search_links, not its title or URL</td></tr><tr><td><code>pinned</code></td><td>boolean</td><td>yes</td><td>true to pin, false to unpin</td></tr></tbody></table><h3 id="delete-link" tabindex="-1"><code>delete_link</code> <a class="header-anchor" href="#delete-link" aria-label="Permalink to “delete_link”">​</a></h3><p><strong>Delete a link</strong> — write, destructive</p><p>Deletes a bookmark and every preserved copy of the page. Two-step: the first call returns a confirmation token, the second call with that token performs the deletion.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the link — the &quot;id&quot; field returned by search_links, not its title or URL</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="bulk-update-links" tabindex="-1"><code>bulk_update_links</code> <a class="header-anchor" href="#bulk-update-links" aria-label="Permalink to “bulk_update_links”">​</a></h3><p><strong>Retag or move many links at once</strong> — write, destructive</p><p>Applies the same tag list and/or target collection to a set of links. Cheaper than one update_link per link, but far blunter: it can only set tags and move collections, and the tag list applies to every link in the set. With replace_tags=true the given tags REPLACE whatever each link had, so an empty tag list strips all tags from all of them. With replace_tags=false the tags are added to the existing ones. Either way this needs a confirmation token, because it rewrites many records at once.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_ids</code></td><td>integer[]</td><td>yes</td><td>Link ids, at most 200</td></tr><tr><td><code>tags</code></td><td>string[]</td><td>yes</td><td>Tag names to apply to every link in the set. Pass [] with replace_tags=true to strip all tags.</td></tr><tr><td><code>replace_tags</code></td><td>boolean</td><td>yes</td><td>true replaces each link&#39;s tags with the given list, false adds to them</td></tr><tr><td><code>collection_id</code></td><td>integer</td><td>no</td><td>Move every link to this collection (owner only)</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="bulk-delete-links" tabindex="-1"><code>bulk_delete_links</code> <a class="header-anchor" href="#bulk-delete-links" aria-label="Permalink to “bulk_delete_links”">​</a></h3><p><strong>Delete many links at once</strong> — write, destructive</p><p>Deletes a set of bookmarks and all their preserved copies. Two-step: the first call returns a confirmation token that is bound to exactly this set of ids — adding an id afterwards invalidates it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_ids</code></td><td>integer[]</td><td>yes</td><td>Link ids, at most 200</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="represerve-link" tabindex="-1"><code>represerve_link</code> <a class="header-anchor" href="#represerve-link" aria-label="Permalink to “represerve_link”">​</a></h3><p><strong>Preserve a link again</strong> — write, destructive</p><p>Has Linkwarden archive the page again. This first DELETES the existing preserved copies and only then re-queues the link, so if the site is gone or now blocks the archiver, the old copies are lost and nothing replaces them. That is why it needs a confirmation token. The work happens in a background worker; get_worker_stats shows the queue.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the link — the &quot;id&quot; field returned by search_links, not its title or URL</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="delete-link-preservations" tabindex="-1"><code>delete_link_preservations</code> <a class="header-anchor" href="#delete-link-preservations" aria-label="Permalink to “delete_link_preservations”">​</a></h3><p><strong>Delete the preserved copies of links</strong> — write, destructive</p><p>Removes the archived screenshot, PDF, readable text and single-file HTML of a set of links while keeping the bookmarks themselves. Useful to reclaim disk space. Unlike represerve_link this does NOT re-archive anything — use that tool if the copies should be recreated.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>link_ids</code></td><td>integer[]</td><td>yes</td><td>Link ids, at most 200</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="create-collection" tabindex="-1"><code>create_collection</code> <a class="header-anchor" href="#create-collection" aria-label="Permalink to “create_collection”">​</a></h3><p><strong>Create a collection</strong> — write</p><p>Creates a collection. Pass parent_id to nest it under an existing collection. New collections are private; use update_collection to publish one.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Collection name</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>parent_id</code></td><td>integer</td><td>no</td><td>Nest the new collection under this one</td></tr><tr><td><code>color</code></td><td>string</td><td>no</td><td>Accent colour as a hex value, e.g. #0ea5e9</td></tr></tbody></table><h3 id="update-collection" tabindex="-1"><code>update_collection</code> <a class="header-anchor" href="#update-collection" aria-label="Permalink to “update_collection”">​</a></h3><p><strong>Update a collection</strong> — write</p><p>Changes a collection. Fields that are not given stay as they are: the tool reads the collection first and merges, because the underlying route rebuilds the member list from the request body and would otherwise remove every collaborator. Only the owner of a collection may update it. To move a collection to the top level pass parent_id=0 — Linkwarden needs an explicit marker for that and ignores null. Setting is_public=true needs a confirmation token: it makes the collection and every link in it readable by anyone who has the URL, without logging in.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>collection_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the collection — the &quot;id&quot; field returned by list_collections</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>parent_id</code></td><td>integer</td><td>no</td><td>Id of the new parent collection, or 0 to move this collection to the top level</td></tr><tr><td><code>is_public</code></td><td>boolean</td><td>no</td><td>true publishes the collection to anyone with the link (needs confirmation), false makes it private again</td></tr><tr><td><code>color</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="delete-collection" tabindex="-1"><code>delete_collection</code> <a class="header-anchor" href="#delete-collection" aria-label="Permalink to “delete_collection”">​</a></h3><p><strong>Delete a collection</strong> — write, destructive</p><p>Deletes a collection. This cascades: every link inside it, every preserved copy of those pages, and every sub-collection below it are deleted too. Two-step: the first call reports how many links would be lost and returns a confirmation token.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>collection_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the collection — the &quot;id&quot; field returned by list_collections</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="create-tags" tabindex="-1"><code>create_tags</code> <a class="header-anchor" href="#create-tags" aria-label="Permalink to “create_tags”">​</a></h3><p><strong>Create tags or change their archival settings</strong> — write</p><p>Creates tags, or updates the ones that already exist — the underlying route is an upsert keyed on the tag name. This is also the only way to set the per-tag archival overrides, which decide how links carrying the tag get preserved. Note that tags are usually created implicitly by create_link and update_link; use this tool when the archival settings matter, or to create a tag before any link uses it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>names</code></td><td>string[]</td><td>yes</td><td>Tag names, at most 50. Existing tags are updated rather than duplicated.</td></tr><tr><td><code>archive_as_screenshot</code></td><td>unknown</td><td>no</td><td>Store a screenshot for links carrying this tag. null inherits the account default.</td></tr><tr><td><code>archive_as_pdf</code></td><td>unknown</td><td>no</td><td>Store a PDF for links carrying this tag. null inherits the account default.</td></tr><tr><td><code>archive_as_readable</code></td><td>unknown</td><td>no</td><td>Store the readable article text (this is what get_link_content reads) for links carrying this tag. null inherits the account default.</td></tr><tr><td><code>archive_as_monolith</code></td><td>unknown</td><td>no</td><td>Store a single-file HTML copy for links carrying this tag. null inherits the account default.</td></tr><tr><td><code>archive_as_wayback_machine</code></td><td>unknown</td><td>no</td><td>Submit the URL to the Internet Archive for links carrying this tag. null inherits the account default.</td></tr><tr><td><code>ai_tag</code></td><td>unknown</td><td>no</td><td>Let the configured AI model assign this tag for links carrying this tag. null inherits the account default.</td></tr></tbody></table><h3 id="rename-tag" tabindex="-1"><code>rename_tag</code> <a class="header-anchor" href="#rename-tag" aria-label="Permalink to “rename_tag”">​</a></h3><p><strong>Rename a tag</strong> — write</p><p>Renames a tag; every link carrying it keeps it. Tag names are unique per account, so renaming a tag to a name that already exists fails — use merge_tags to fold two tags into one instead.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>tag_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the tag — the &quot;id&quot; field returned by list_tags</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>New tag name</td></tr></tbody></table><h3 id="delete-tags" tabindex="-1"><code>delete_tags</code> <a class="header-anchor" href="#delete-tags" aria-label="Permalink to “delete_tags”">​</a></h3><p><strong>Delete tags</strong> — write, destructive</p><p>Deletes one or more tags. The links keep existing, they just lose the tag. Two-step: the first call returns a confirmation token bound to exactly this set of ids.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>tag_ids</code></td><td>integer[]</td><td>yes</td><td>Tag ids, at most 50</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="merge-tags" tabindex="-1"><code>merge_tags</code> <a class="header-anchor" href="#merge-tags" aria-label="Permalink to “merge_tags”">​</a></h3><p><strong>Merge tags into one</strong> — write, destructive</p><p>Folds several tags into a single new one: every link that carried any of the source tags gets the new tag, and the source tags are deleted. Two things to know before calling this. The new tag is created from scratch, so the name must not already be in use by this account — merging into an existing name fails. And the per-tag archival settings of the source tags are not carried over; set them again with create_tags afterwards if they mattered.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>tag_ids</code></td><td>integer[]</td><td>yes</td><td>Ids of the tags to merge away</td></tr><tr><td><code>new_name</code></td><td>string</td><td>yes</td><td>Name of the new tag. Must not exist yet.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table><h3 id="create-rss-subscription" tabindex="-1"><code>create_rss_subscription</code> <a class="header-anchor" href="#create-rss-subscription" aria-label="Permalink to “create_rss_subscription”">​</a></h3><p><strong>Subscribe to an RSS feed</strong> — write</p><p>Subscribes to an RSS or Atom feed. Linkwarden polls it and files every new entry as a link in the given collection, preserving the pages according to the account defaults. Linkwarden fetches the feed once immediately, so a feed that is unreachable or points at a private address is rejected right away. Subscription names must be unique per account, and instances cap the number of subscriptions (20 by default).</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Name for the subscription, unique within the account</td></tr><tr><td><code>url</code></td><td>string</td><td>yes</td><td>Feed URL, including the scheme</td></tr><tr><td><code>collection_id</code></td><td>integer</td><td>no</td><td>Collection the entries land in. Mutually exclusive with collection_name.</td></tr><tr><td><code>collection_name</code></td><td>string</td><td>no</td><td>Collection by name; it is created if it does not exist. Mutually exclusive with collection_id.</td></tr></tbody></table><h3 id="delete-rss-subscription" tabindex="-1"><code>delete_rss_subscription</code> <a class="header-anchor" href="#delete-rss-subscription" aria-label="Permalink to “delete_rss_subscription”">​</a></h3><p><strong>Delete an RSS subscription</strong> — write, destructive</p><p>Stops polling a feed. Links that were already created from it stay where they are — only the subscription goes away.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>rss_subscription_id</code></td><td>integer</td><td>yes</td><td>Numeric id of the RSS subscription — the &quot;id&quot; field returned by list_rss_subscriptions</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Confirmation token from a previous call of this tool with the same arguments. Omit on the first call.</td></tr></tbody></table>`,117)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};